def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--inputs', type=Path, required=True)
    parser.add_argument('--out', type=Path, required=True)
    args = parser.parse_args()
    for name, expected in INPUT_SHA256.items():
        actual = hashlib.sha256((args.inputs/name).read_bytes()).hexdigest()
        if actual != expected:
            raise ValueError(f'{name} differs from the episode used to fit the correction constants')
    with np.load(args.inputs/'reconstruction.npz') as archive:
        baseline_world = archive['T_world_mesh'].astype(np.float64)
    camera = json.loads((args.inputs/'camera.json').read_text())
    K = np.array(camera['K'], dtype=np.float64)
    world_cam = np.array(camera['T_world_cam'], dtype=np.float64)
    baseline = np.linalg.inv(world_cam)[None] @ baseline_world
    selected = CORRECTIONS
    assert selected.shape == (len(baseline), 5)
    changed = np.linalg.norm(selected, axis=1) > 1e-10
    result = baseline_world.copy()
    r = Rotation.from_rotvec(selected[:, :3]*.03).as_matrix() @ baseline[:, :3, :3]
    uv = baseline[:, :3, 3] @ K.T
    uv = uv[:, :2]/uv[:, 2:]
    xy = uv+selected[:, 3:]
    rays = np.column_stack([(xy-K[:2, 2])/K[0, 0], np.ones(len(baseline))])
    translation = rays/np.linalg.norm(rays, axis=1)[:, None]*np.linalg.norm(baseline[:, :3, 3], axis=1)[:, None]
    refined = baseline.copy()
    refined[:, :3, :3] = r
    refined[:, :3, 3] = translation
    result[changed] = (world_cam[None] @ refined)[changed]
    assert result.shape == (700, 4, 4) and result.dtype == np.float64
    assert np.isfinite(result).all()
    final_camera = np.linalg.inv(world_cam)[None] @ result
    radius_error = np.abs(np.linalg.norm(final_camera[:, :3, 3], axis=1)-np.linalg.norm(baseline[:, :3, 3], axis=1))
    assert radius_error.max() < 1e-12
    assert np.array_equal(result[~changed], baseline_world[~changed])
    args.out.parent.mkdir(parents=True, exist_ok=True)
    np.savez_compressed(args.out, T_world_mesh=result)
    print(f'Wrote {len(result)} float64 poses; {changed.sum()} corrected, {(~changed).sum()} exact baseline.')


if __name__ == '__main__':
    main()
